'use strict';
function internationalPhone(form){const input=form.elements.phone,code=form.elements.phoneCode.value;let number=input.value.replace(/[\s().-]/g,'');if(number.startsWith('00'))number='+'+number.slice(2);if(number.startsWith('+')){if(code&& !number.startsWith(code))throw Error(translateText('Số điện thoại không khớp mã quốc gia đã chọn'));}else{if(!code)throw Error(translateText('Nhập số quốc tế bắt đầu bằng +'));if(['+33','+84','+32','+41','+49','+44'].includes(code))number=number.replace(/^0/,'');number=code+number;}if(!/^\+[1-9]\d{6,14}$/.test(number))throw Error(translateText('Số điện thoại không hợp lệ'));return number;}
